WITH cleaned AS (SELECT *, CAST(txn_time AS DATE) AS txn_time_day FROM transactions WHERE txn_time > TIMESTAMP '2023-11-05 20:00:00' AND merchant IS NOT NULL), prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) AS prev_txn_time FROM cleaned), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, COUNT(*) AS event_count, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, STDDEV_SAMP(amount) AS amount_stddev, SUM(CASE WHEN txn_type = 'DEBIT' THEN session_id ELSE 0 END) AS debit_session_id, MAX(session_id) AS max_session_id, COUNT(DISTINCT id) AS distinct_ids FROM sessions_transactions GROUP BY DATE_TRUNC('QUARTER', txn_time) ORDER BY quarter_start DESC NULLS FIRST
